function validate([nums]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  for (const num of nums) {
    if (!Number.isInteger(num) || num < 2 || num > 1000) return 'Each value is a whole number from 2 to 1000.';
    for (let d = 2; d * d <= num; d++) if (num % d === 0) return `${num} is not prime; every value must be prime.`;
  }
  return null;
}

