function minBitwiseArray(nums) {
  // Try every candidate from 0 upwards; x | (x + 1) is never below x, so nothing above num can work.
  return nums.map(num => {
    for (let x = 0; x <= num; x++) {
      if ((x | (x + 1)) === num) return x;
    }
    return -1;
  });
}

