function generate(rand, size) {
  const primes = [];
  for (let value = 2; value <= 1000; value++) {
    let prime = true;
    for (let d = 2; d * d <= value; d++) if (value % d === 0) { prime = false; break; }
    if (prime) primes.push(value);
  }
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  // Small inputs often draw from the first dozen primes, so 2 and repeated values show up.
  const pool = size === 'large' || rand() < 0.5 ? primes : primes.slice(0, 12);
  return [Array.from({ length: n }, () => pool[Math.floor(rand() * pool.length)])];
}
